// Tests for the front side's levels on the example flight. Run: npm test.
// Code generated by Claude (Anthropic), an AI system.
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { createMachine } from '../src/engine.js';
import { CELLS, CREW, SHIP } from '../src/config.js';
import { exampleFlight, MISSION } from '../src/demo-crew.js';
import { assess, assessShip, headline, headlineFor, topLevel, LEVEL, RULES, RULE_NOTES, SLOW_MEASURES, EXPECTED } from '../src/state-levels.js';
import { KIT_HOURS, medicineValue } from '../src/quicklog.js';

function flightMachine(extra = []) {
  const machine = createMachine({ cells: CELLS, crew: [...CREW, SHIP], state: { aiWorks: true, doctorOnBoard: false, linkToEarth: true } });
  const events = [...exampleFlight(CREW), ...extra].sort((a, b) => new Date(a.time) - new Date(b.time));
  for (const ev of events) {
    if (ev.kind === 'reading') machine.receive({ ...ev.reading, person: ev.person, time: ev.time });
    else if (ev.kind === 'review') machine.review(ev.person, ev.time);
  }
  return machine;
}
const person = (id) => CREW.find((p) => p.id === id);
const now = new Date(MISSION.today);

test("Elly: the endurance forecast shows up as something to pay attention to", () => {
  const a = assess({ machine: flightMachine(), person: person('crew-2'), cells: CELLS, mission: MISSION, now });
  const fc = a.body.items.find((x) => x.kind === 'forecast' && x.cell.indicator === 'vo2max');
  assert.ok(fc);
  assert.equal(fc.level, LEVEL.ATTENTION);
});

test('Member 4: many bad-mood days make the mind "needs action"', () => {
  const a = assess({ machine: flightMachine(), person: person('crew-4'), cells: CELLS, mission: MISSION, now });
  assert.equal(a.psyche.level, LEVEL.ACTION);
});

test('changes common in flight (temperature up, short sleep) are information on the page, never the headline', () => {
  const machine = flightMachine();
  const seen = new Set();
  for (const p of CREW) {
    const a = assess({ machine, person: p, cells: CELLS, mission: MISSION, now });
    assert.ok(a.body.items.every((x) => x.kind !== 'expected'), p.id);
    for (const x of a.info.filter((i) => i.kind === 'expected')) {
      assert.equal(x.level, LEVEL.FINE);
      assert.ok(x.expected.source && x.expected.url && x.expected.draft, 'the band carries its source and is a draft');
      seen.add(x.cell.indicator);
    }
  }
  assert.deepEqual([...seen].sort(), ['sleep', 'temp']);
});

test('a camera alarm after "Are you okay?" makes the body "urgent"', () => {
  const alarm = { v: 1, kind: 'reading', time: new Date(now.getTime() - 60 * 60 * 1000).toISOString(), person: 'crew-1', state: { aiWorks: true, doctorOnBoard: false, linkToEarth: true }, reading: { source: 'camera', indicator: 'camera', value: 'chest_grab_no_answer' } };
  const a = assess({ machine: flightMachine([alarm]), person: person('crew-1'), cells: CELLS, mission: MISSION, now });
  assert.equal(a.body.level, LEVEL.URGENT);
  assert.equal(a.body.items[0].kind, 'camera');
});

test('the ship is assessed apart from the people', () => {
  const s = assessShip({ machine: flightMachine(), ship: SHIP, cells: CELLS, mission: MISSION, now });
  assert.ok(s.level >= LEVEL.FINE);
  assert.ok(s.items.every((x) => x.cell.section === 'env'));
});

test("the message follows the team's template", () => {
  assert.equal(headline('14 Nov 2026', LEVEL.FINE, LEVEL.FINE), 'As of 14 Nov 2026, your physical and mental condition is excellent. Keep it up, well done!');
  assert.equal(headline('14 Nov 2026', LEVEL.ATTENTION, LEVEL.FINE), 'As of 14 Nov 2026, your physical condition needs attention, your mental condition is excellent.');
  assert.equal(headline('14 Nov 2026', LEVEL.FINE, LEVEL.ACTION), 'As of 14 Nov 2026, your mental condition needs action, your physical condition is excellent.');
});

// ---------- safety and calm (drafts) on a small made-up flight ----------
const DAY = 24 * 60 * 60 * 1000;
const MIS = { name: 'test flight', launch: '2026-01-01T00:00:00.000Z', landing: '2026-07-01T00:00:00.000Z', today: '2026-05-01T12:00:00.000Z' };
const at = (n, hour = 8) => new Date(Date.parse(MIS.launch) + n * DAY + hour * 60 * 60 * 1000).toISOString();
const fresh = (state) => createMachine({ cells: CELLS, crew: [...CREW, SHIP], state: state || { aiWorks: true, doctorOnBoard: false, linkToEarth: true } });
const put = (m, n, indicator, value, who = 'crew-1', extra = {}) => m.receive({ person: who, source: indicator, indicator, value, time: at(n), ...extra });
// One ordinary day: every daily measure in its norm, and the check-in.
function ordinaryDay(m, n, who = 'crew-1') {
  for (const [ind, v] of [['pulse', 70], ['bp', { sys: 112, dia: 72 }], ['temp', 36.7], ['sleep', 7.2], ['resp', 14], ['fluid', 2700], ['radiation', 100 + n * 0.3], ['mood', 'good'], ['attitude', 'energetic']]) put(m, n, ind, v, who);
}
function ordinaryDays(m, from, to, who = 'crew-1') { for (let n = from; n <= to; n += 1) ordinaryDay(m, n, who); }
const judgeOn = (m, n, who = 'crew-1') => assess({ machine: m, person: person(who), cells: CELLS, mission: MIS, now: new Date(at(n, 12)) });
const itemOf = (a, indicator) => [...a.body.items, ...a.info].find((x) => x.cell && x.cell.indicator === indicator && x.kind !== 'stale');

test('temperature: the in-flight rise is common only within its band, and a fever never is', () => {
  const late = (value) => { const m = fresh(); ordinaryDays(m, 90, 100); put(m, 100, 'temp', value); return judgeOn(m, 100); };
  const warm = late(37.9); // day 100: the rise has built up; below the fever line
  assert.equal(itemOf(warm, 'temp').kind, 'expected');
  assert.equal(warm.body.level, LEVEL.FINE);
  const fever = late(38.0); // CDC: 38 °C or more is a fever
  assert.equal(itemOf(fever, 'temp').kind, 'red');
  assert.equal(fever.body.level, LEVEL.ACTION);
  assert.equal(late(40.6).body.level, LEVEL.URGENT);
  assert.equal(late(34.9).body.level, LEVEL.URGENT);
  // Day 3: the rise has hardly begun, so 37.6 °C is not "common in flight": watched once, attention when it stays.
  const m = fresh();
  ordinaryDays(m, 0, 2);
  put(m, 3, 'temp', 37.6);
  assert.equal(itemOf(judgeOn(m, 3), 'temp').kind, 'watch');
  put(m, 4, 'temp', 37.6);
  put(m, 5, 'temp', 37.6);
  assert.equal(itemOf(judgeOn(m, 5), 'temp').kind, 'out');
  assert.equal(judgeOn(m, 5).body.level, LEVEL.ATTENTION);
  // Before launch nothing is "common in flight".
  const pre = fresh();
  put(pre, -5, 'temp', 37.6);
  assert.notEqual(itemOf(judgeOn(pre, -5), 'temp').kind, 'expected');
  assert.ok(EXPECTED.temp.below <= 38.0, 'the band ends below the fever line');
});

test('sleep: 5 hours or more is common in flight; shorter nights are watched, and need attention when they go on', () => {
  const m = fresh();
  ordinaryDays(m, 80, 99);
  for (let n = 80; n <= 99; n += 1) put(m, n, 'sleep', 6.0, 'crew-1', { time: at(n, 9) });
  assert.equal(itemOf(judgeOn(m, 99), 'sleep').kind, 'expected');
  put(m, 100, 'sleep', 5.0);
  assert.equal(itemOf(judgeOn(m, 100), 'sleep').kind, 'expected');
  // A run of common 6-hour nights does not count toward a streak: one night under 5 hours is only watched.
  put(m, 101, 'sleep', 4.5);
  const one = judgeOn(m, 101);
  assert.equal(itemOf(one, 'sleep').kind, 'watch');
  assert.equal(one.body.level, LEVEL.FINE);
  put(m, 102, 'sleep', 4.5);
  put(m, 103, 'sleep', 4.5);
  assert.equal(judgeOn(m, 103).body.level, LEVEL.ATTENTION);
  for (let n = 104; n <= 107; n += 1) put(m, n, 'sleep', 4.5);
  assert.equal(judgeOn(m, 107).body.level, LEVEL.ACTION, `${RULES.outStreakForActionDaily} short nights in a row`);
});

test('a reading past a red limit raises its level at once; a daily vital just outside the norm waits for a repeat', () => {
  const m = fresh();
  ordinaryDays(m, 110, 120);
  put(m, 120, 'spo2', 85);
  const a = judgeOn(m, 120);
  const red = itemOf(a, 'spo2');
  assert.equal(red.kind, 'red');
  assert.equal(red.level, LEVEL.URGENT);
  assert.equal(red.red.source, 'MedlinePlus (NIH)');
  assert.equal(a.body.items[0], red, 'the red item comes first');
  // Heart rate 58: outside the Earth norm, far inside its red limits. Once is watched, three in a row is attention.
  const p = fresh();
  ordinaryDays(p, 110, 120);
  put(p, 120, 'pulse', 58, 'crew-1', { time: at(120, 9) });
  assert.equal(judgeOn(p, 120).body.level, LEVEL.FINE);
  put(p, 121, 'pulse', 58);
  put(p, 122, 'pulse', 58);
  assert.equal(judgeOn(p, 122).body.level, LEVEL.ATTENTION);
  // A measure taken rarely (eye pressure, on flight days 30 and 90) is judged on its one reading.
  const e = fresh();
  ordinaryDays(e, 85, 90);
  put(e, 90, 'eyePressure', 24);
  assert.equal(itemOf(judgeOn(e, 90), 'eyePressure').level, LEVEL.ATTENTION);
});

test('forecast: noisy daily vitals give no forecast alert; slow measures and a clear trend do', () => {
  const m = flightMachine();
  for (const p of CREW) {
    const a = assess({ machine: m, person: p, cells: CELLS, mission: MISSION, now });
    for (const it of a.body.items.filter((x) => x.kind === 'forecast')) assert.ok(SLOW_MEASURES.includes(it.cell.indicator), `${p.id} ${it.cell.indicator}`);
  }
  // Temperature rising 0.1 °C a day for 8 days, still inside the norm: the line clearly outruns the scatter.
  const t = fresh();
  for (let n = 10; n <= 17; n += 1) put(t, n, 'temp', Math.round((36.2 + 0.1 * (n - 10)) * 10) / 10);
  const rising = itemOf(judgeOn(t, 17), 'temp');
  assert.equal(rising.kind, 'forecast');
  assert.ok(rising.m.clearTrend);
  // The same rise over only 3 days is too few points to call clear.
  const s = fresh();
  for (let n = 10; n <= 12; n += 1) put(s, n, 'temp', Math.round((36.6 + 0.2 * (n - 10)) * 10) / 10);
  assert.equal(itemOf(judgeOn(s, 12), 'temp'), undefined);
});

test('no fresh data: silence is never "excellent"', () => {
  const m = fresh();
  ordinaryDays(m, 100, 116);
  assert.equal(headlineFor('1 May 2026', judgeOn(m, 116)), 'As of 1 May 2026, your physical and mental condition is excellent. Keep it up, well done!');
  const silent = judgeOn(m, 120); // four days with no reading at all
  assert.equal(silent.fresh.body, false);
  assert.equal(silent.fresh.mind, false);
  assert.ok(silent.fresh.missing.some((x) => x.indicator === 'pulse' && x.days === 4));
  assert.equal(headlineFor('1 May 2026', silent), 'As of 1 May 2026, there is not enough fresh data to judge your physical and mental condition.');
  // Body readings go on, the check-in stops.
  for (let n = 117; n <= 120; n += 1) for (const [ind, v] of [['pulse', 70], ['bp', { sys: 112, dia: 72 }], ['temp', 36.7], ['sleep', 7.2], ['resp', 14], ['fluid', 2700], ['radiation', 140]]) put(m, n, ind, v);
  assert.equal(headlineFor('1 May 2026', judgeOn(m, 120)), 'As of 1 May 2026, there is not enough fresh data to judge your mental condition, your physical condition is excellent.');
  // A problem comes before missing data.
  put(m, 120, 'spo2', 94);
  assert.equal(headlineFor('1 May 2026', judgeOn(m, 120)), 'As of 1 May 2026, your physical condition needs attention, there is not enough fresh data to judge your mental condition.');
  // An empty record is not "excellent" either.
  assert.equal(headlineFor('1 May 2026', judgeOn(fresh(), 120)), 'As of 1 May 2026, there is not enough fresh data to judge your physical and mental condition.');
});

test("ship: a cabin value past the ship's own limit reaches every person's message as a ship alarm", () => {
  const m = fresh();
  ordinaryDays(m, 110, 120, 'crew-1');
  ordinaryDays(m, 110, 120, 'crew-2');
  m.receive({ person: 'ship', source: 'co2-sensor', indicator: 'co2', value: 4.2, time: at(120) });
  const caution = judgeOn(m, 120);
  assert.equal(caution.ship.level, LEVEL.FINE, 'CO2 above the norm but inside the ship limit stays on the ship row');
  assert.equal(assessShip({ machine: m, ship: SHIP, cells: CELLS, mission: MIS, now: new Date(at(120, 12)) }).level, LEVEL.ATTENTION);
  m.receive({ person: 'ship', source: 'pressure-sensor', indicator: 'cabinPressure', value: 30, time: at(120, 9) });
  for (const who of ['crew-1', 'crew-2']) {
    const a = judgeOn(m, 120, who);
    assert.equal(a.ship.level, LEVEL.URGENT, who);
    assert.equal(a.body.level, LEVEL.FINE, "the ship's air is not the person's body");
    assert.equal(topLevel(a), LEVEL.URGENT);
    assert.equal(headlineFor('1 May 2026', a), 'Ship emergency: follow ship procedures. As of 1 May 2026, your physical and mental condition is excellent.');
  }
});

test('headline drafts: ship caution, and no doctor to call', () => {
  assert.equal(headline('1 May 2026', LEVEL.FINE, LEVEL.ATTENTION, { shipLevel: LEVEL.ACTION }), 'Ship caution: follow ship procedures. As of 1 May 2026, your mental condition needs attention, your physical condition is excellent.');
  assert.equal(headline('1 May 2026', LEVEL.URGENT, LEVEL.FINE, { doctorReachable: false }), 'As of 1 May 2026, your physical condition needs help: the crew on board has been alerted, your mental condition is excellent.');
  assert.equal(headline('1 May 2026', LEVEL.URGENT, LEVEL.FINE), 'As of 1 May 2026, your physical condition needs help: a doctor has been called, your mental condition is excellent.');
  // The camera with no doctor on board and no link: urgent, and the message says who was alerted.
  const m = fresh({ aiWorks: true, doctorOnBoard: false, linkToEarth: false });
  ordinaryDays(m, 110, 120);
  put(m, 120, 'camera', 'chest_grab_no_answer');
  const a = judgeOn(m, 120);
  assert.equal(a.doctorReachable, false);
  assert.match(headlineFor('1 May 2026', a), /needs help: the crew on board has been alerted/);
});

test('mind: the placeholder rule needs 6 low days of the last 14 for attention and 8 for action', () => {
  const lowDays = (k) => {
    const m = fresh();
    ordinaryDays(m, 106, 120);
    for (let n = 120 - k + 1; n <= 120; n += 1) put(m, n, 'mood', 'bad', 'crew-1', { time: at(n, 9) });
    return judgeOn(m, 120).psyche.level;
  };
  assert.equal(lowDays(RULES.badDaysForAttention - 1), LEVEL.FINE);
  assert.equal(lowDays(RULES.badDaysForAttention), LEVEL.ATTENTION);
  assert.equal(lowDays(RULES.badDaysForAction), LEVEL.ACTION);
});

test('example flight: most days calm, the real problems still flagged', () => {
  const machine = createMachine({ cells: CELLS, crew: [...CREW, SHIP], state: { aiWorks: true, doctorOnBoard: false, linkToEarth: true } });
  const events = exampleFlight(CREW);
  const launch = Date.parse(MISSION.launch);
  const end = Date.parse(MISSION.today);
  const above = Object.fromEntries(CREW.map((p) => [p.id, 0]));
  let days = 0;
  let i = 0;
  for (let t = launch + DAY + 18 * 60 * 60 * 1000; t <= end; t += DAY) {
    for (; i < events.length && Date.parse(events[i].time) <= t; i += 1) {
      const ev = events[i];
      if (ev.kind === 'reading') machine.receive({ ...ev.reading, person: ev.person, time: ev.time });
    }
    days += 1;
    for (const p of CREW) if (topLevel(assess({ machine, person: p, cells: CELLS, mission: MISSION, now: new Date(t) })) > LEVEL.FINE) above[p.id] += 1;
  }
  for (const id of ['crew-1', 'crew-2', 'crew-3']) assert.ok(above[id] < days * 0.1, `${id}: ${above[id]} of ${days} days above fine`);
  for (; i < events.length; i += 1) { const ev = events[i]; if (ev.kind === 'reading') machine.receive({ ...ev.reading, person: ev.person, time: ev.time }); }
  assert.equal(assess({ machine, person: person('crew-4'), cells: CELLS, mission: MISSION, now }).psyche.level, LEVEL.ACTION, "member 4's mood slide");
  assert.ok(assess({ machine, person: person('crew-2'), cells: CELLS, mission: MISSION, now }).body.items.some((x) => x.kind === 'forecast' && x.cell.indicator === 'vo2max'), "Elly's endurance");
});

// ---------- reviewer's fixes (drafts): nothing really wrong may read "excellent" ----------
const minutesAfter = (n, hour, min) => new Date(Date.parse(at(n, hour)) + min * 60 * 1000).toISOString();

test('a reading past a red limit, then a repeat still outside the norm: never "excellent"', () => {
  for (const [indicator, crisis, repeat] of [['bp', { sys: 200, dia: 125 }, { sys: 175, dia: 115 }], ['pulse', 180, 125], ['resp', 32, 23], ['temp', 34.6, 35.4]]) {
    const m = fresh();
    ordinaryDays(m, 110, 120);
    put(m, 120, indicator, crisis, 'crew-1', { time: at(120, 9) });
    put(m, 120, indicator, repeat, 'crew-1', { time: minutesAfter(120, 9, 5) });
    const a = judgeOn(m, 120);
    const it = itemOf(a, indicator);
    assert.equal(it.kind, 'out', indicator);
    assert.ok(it.m.redInRun, `${indicator}: the run holds the red reading`);
    assert.equal(a.body.level, LEVEL.ATTENTION, indicator);
    assert.doesNotMatch(headlineFor('1 May 2026', a), /excellent\. Keep it up/, indicator);
  }
  // Back inside the norm, the run is over.
  const m = fresh();
  ordinaryDays(m, 110, 120);
  put(m, 120, 'bp', { sys: 200, dia: 125 }, 'crew-1', { time: at(120, 9) });
  put(m, 120, 'bp', { sys: 175, dia: 115 }, 'crew-1', { time: minutesAfter(120, 9, 5) });
  put(m, 120, 'bp', { sys: 118, dia: 76 }, 'crew-1', { time: at(120, 10) });
  assert.equal(judgeOn(m, 120).body.level, LEVEL.FINE);
});

test('two or more vital signs outside the norm at the same time count at once (NEWS2), other measures do not', () => {
  const together = (extra, day = 40) => {
    const m = fresh();
    ordinaryDays(m, 30, day);
    for (const [indicator, value, time] of extra) put(m, day, indicator, value, 'crew-1', { time: time || at(day, 9) });
    return judgeOn(m, day);
  };
  const two = together([['pulse', 125], ['resp', 24]]);
  assert.equal(two.body.level, LEVEL.ATTENTION);
  for (const ind of ['pulse', 'resp']) {
    const it = itemOf(two, ind);
    assert.equal(it.kind, 'out', ind);
    assert.deepEqual([...it.together].sort(), ['pulse', 'resp']);
  }
  assert.equal(RULE_NOTES.vitalsTogether.draft, true);
  assert.match(RULE_NOTES.vitalsTogether.url, /^https:\/\/www\.rcp\.ac\.uk\//);
  // One vital sign alone still waits for a repeat; sleep is not a vital sign.
  assert.equal(together([['pulse', 125]]).body.level, LEVEL.FINE);
  assert.equal(together([['pulse', 125], ['sleep', 4.5]]).body.level, LEVEL.FINE);
  // Not at the same time: the breathing reading is more than a day older than the pulse reading.
  const apart = fresh();
  ordinaryDays(apart, 30, 39);
  put(apart, 39, 'resp', 24, 'crew-1', { time: at(39, 9) });
  put(apart, 40, 'pulse', 125, 'crew-1', { time: at(40, 10) });
  assert.equal(assess({ machine: apart, person: person('crew-1'), cells: CELLS, mission: MIS, now: new Date(at(40, 11)) }).body.level, LEVEL.FINE);
});

test('exercise: a reading that is only recorded never changes the judgement of the person at rest', () => {
  const m = fresh();
  ordinaryDays(m, 100, 115);
  for (let n = 116; n <= 120; n += 1) {
    for (const [ind, v] of [['bp', { sys: 112, dia: 72 }], ['temp', 36.7], ['sleep', 7.2], ['resp', 14], ['fluid', 2700], ['radiation', 140], ['mood', 'good'], ['attitude', 'energetic']]) put(m, n, ind, v);
    put(m, n, 'pulse', 120); // at rest, outside the norm, inside the red limits, five mornings in a row
  }
  assert.equal(judgeOn(m, 120).body.level, LEVEL.ATTENTION);
  put(m, 120, 'pulse', 150, 'crew-1', { time: at(120, 10), context: 'exercise' });
  const a = judgeOn(m, 120);
  assert.equal(a.body.level, LEVEL.ATTENTION, 'the exercise reading does not clear the run at rest');
  const it = itemOf(a, 'pulse');
  assert.equal(it.m.last.value, 120);
  assert.equal(it.m.streak, 5);
  assert.equal(new Date(it.m.runFrom).toISOString(), at(116));
  assert.equal(it.m.list[it.m.list.length - 1].context, 'exercise', 'the screen still gets every reading');
});

// ---------- final review fixes of 15 Nov 2026 (drafts): an alarm can be called off; own logs can say "tell someone" ----------

test('a temperature of 35.0 °C is the urgent hypothermia limit: NEWS2 scores 35.0 or less red; MedlinePlus stays the first source', () => {
  const m = fresh();
  ordinaryDays(m, 110, 120);
  put(m, 120, 'temp', 35.0, 'crew-1', { time: at(120, 9) });
  const a = judgeOn(m, 120);
  const it = itemOf(a, 'temp');
  assert.equal(it.kind, 'red');
  assert.equal(it.level, LEVEL.URGENT);
  assert.deepEqual([it.red.when, it.red.value, it.red.source, it.red.source2, it.red.draft], ['atOrBelow', 35, 'MedlinePlus (NIH)', 'RCP NEWS2, 2017', true]);
  assert.match(it.red.url2, /^https:\/\/www\.rcp\.ac\.uk\//);
  assert.equal(headlineFor('1 May 2026', a), 'As of 1 May 2026, your physical condition needs help: a doctor has been called, your mental condition is excellent.');
  const warmer = fresh();
  ordinaryDays(warmer, 110, 120);
  put(warmer, 120, 'temp', 35.1, 'crew-1', { time: at(120, 9) });
  assert.notEqual(itemOf(judgeOn(warmer, 120), 'temp').kind, 'red', '35.1 is outside the norm, not past the red limit');
});

const CALM = 'As of 1 May 2026, your physical and mental condition is excellent. Keep it up, well done!';

test('"I am okay" after a camera or Help key alarm calls the alarm off; the alarm stays in the record', () => {
  const m = fresh();
  ordinaryDays(m, 110, 120);
  put(m, 120, 'camera', 'chest_grab_help', 'crew-1', { source: 'help-key', time: at(120, 9) });
  assert.equal(judgeOn(m, 120).body.level, LEVEL.URGENT);
  put(m, 120, 'camera', 'chest_grab_ok', 'crew-1', { source: 'false-alarm', time: minutesAfter(120, 9, 5) });
  const a = judgeOn(m, 120);
  assert.equal(a.body.level, LEVEL.FINE, 'Today and Messages calm down');
  assert.ok(!a.body.items.some((x) => x.kind === 'camera'));
  assert.equal(headlineFor('1 May 2026', a), CALM);
  const note = a.info.find((x) => x.kind === 'camera-cleared');
  assert.equal(note.level, LEVEL.FINE);
  assert.equal(note.source, 'false-alarm');
  assert.deepEqual([note.alarm.value, note.alarm.source], ['chest_grab_help', 'help-key']);
  assert.equal(m.history('crew-1', 'camera').length, 2, 'the alarm stays in the record');
  // A new alarm after the all-clear is urgent again, and "asleep" calls nothing off.
  put(m, 120, 'camera', 'chest_grab_no_answer', 'crew-1', { source: 'camera', time: at(120, 10) });
  put(m, 120, 'camera', 'sleeping', 'crew-1', { source: 'camera', time: minutesAfter(120, 10, 30) });
  const again = judgeOn(m, 120);
  assert.equal(again.body.level, LEVEL.URGENT);
  assert.equal(again.body.items[0].value, 'chest_grab_no_answer');
  assert.ok(!again.info.some((x) => x.kind === 'camera-cleared'));
  // An "okay" from before the alarm calls nothing off.
  const early = fresh();
  ordinaryDays(early, 110, 120);
  put(early, 120, 'camera', 'chest_grab_ok', 'crew-1', { source: 'camera', time: at(120, 8.5) });
  put(early, 120, 'camera', 'chest_grab_no_answer', 'crew-1', { source: 'camera', time: at(120, 9) });
  assert.equal(judgeOn(early, 120).body.level, LEVEL.URGENT);
});

const hoursBefore = (n, hours) => new Date(Date.parse(at(n, 12)) - hours * 60 * 60 * 1000).toISOString(); // judgeOn looks at 12:00
const tellOf = (a) => a.body.items.find((x) => x.kind === 'tell');
const ATTENTION_ONLY = 'As of 1 May 2026, your physical condition needs attention, your mental condition is excellent.';

test('eyes: an answer other than "no change" asks to tell the flight surgeon, until a later "no change" (draft)', () => {
  const m = fresh();
  ordinaryDays(m, 100, 120);
  put(m, 120, 'visionCheck', 'grid changed', 'crew-1', { source: 'eye-self-check', time: at(120, 9) });
  const check = (a) => {
    const it = tellOf(a);
    assert.deepEqual([it.rule, it.level, it.cell.indicator, it.who, it.draft, it.private], ['eye-answer', LEVEL.ATTENTION, 'visionCheck', 'flight surgeon', true, false]);
    assert.match(it.text, /^"Some grid lines look wavy, broken or missing", your eye self-check answer of GMT \d+\/09:00\. Worth telling your flight surgeon \(a draft rule; who reads these answers between the eye exams is the team's open decision\)/);
    assert.equal(it.short, 'Grid lines look wrong: tell your flight surgeon');
    assert.ok(it.steps.length >= 2 && it.steps.every((s) => typeof s === 'string' && s));
    assert.equal(it.title, 'Eyes (SANS): vision self-check');
    assert.equal(a.body.level, LEVEL.ATTENTION);
    assert.equal(headlineFor('1 May 2026', a), ATTENTION_ONLY);
  };
  check(judgeOn(m, 120));
  ordinaryDays(m, 121, 160);
  check(judgeOn(m, 160)); // forty days on, with no later answer: still there
  put(m, 160, 'visionCheck', 'vision changed', 'crew-1', { source: 'eye-self-check', time: at(160, 9) });
  assert.match(tellOf(judgeOn(m, 160)).text, /^"My near or far vision has changed"/);
  put(m, 160, 'visionCheck', 'no change', 'crew-1', { source: 'eye-self-check', time: at(160, 10) });
  assert.equal(judgeOn(m, 160).body.level, LEVEL.FINE);
  assert.equal(headlineFor('1 May 2026', judgeOn(m, 160)), CALM);
});

test(`symptoms: one rated ${RULES.symptomTellAt} or more of 10 in the last ${RULES.symptomHours} hours asks to tell the crew medical officer (draft); the log stays private`, () => {
  const logged = (entries) => {
    const m = fresh();
    ordinaryDays(m, 110, 120);
    for (const [value, hours] of entries) put(m, 120, 'symptoms', value, 'crew-1', { source: 'symptom-log', time: hoursBefore(120, hours) });
    return judgeOn(m, 120);
  };
  assert.equal(logged([[{ symptom: 'backPain', severity: RULES.symptomTellAt - 1 }, 1]]).body.level, LEVEL.FINE);
  const a = logged([[{ symptom: 'headache', severity: 8 }, 5], [{ symptom: 'other', severity: 10, note: 'chest pain and short of breath' }, 1]]);
  const it = tellOf(a);
  assert.deepEqual([it.rule, it.level, it.cell.indicator, it.who, it.draft, it.private], ['strong-symptom', LEVEL.ATTENTION, 'symptoms', 'crew medical officer', true, true]);
  assert.match(it.text, /^Something else, 10 of 10: chest pain and short of breath \(GMT \d+\/11:00\); Headache, 8 of 10 \(GMT \d+\/07:00\)\. A symptom of 8 or more of 10 in the last 24 hours: tell the crew medical officer \(a draft rule; the team decides\)\.$/);
  assert.equal(it.short, 'Something else, 10 of 10: chest pain and short of breath: tell the crew medical officer');
  assert.ok(it.steps.some((s) => s.includes('hold the Help key')));
  assert.ok(it.steps.some((s) => s.includes('sent only if you choose')));
  assert.deepEqual(it.entries.map((x) => x.value.severity), [10, 8], 'newest first');
  assert.equal(headlineFor('1 May 2026', a), ATTENTION_ONLY, 'a 10 of 10 is never "excellent"');
  assert.equal(logged([[{ symptom: 'backPain', severity: RULES.symptomTellAt }, RULES.symptomHours - 1]]).body.level, LEVEL.ATTENTION);
  assert.equal(logged([[{ symptom: 'backPain', severity: 10 }, RULES.symptomHours + 1]]).body.level, LEVEL.FINE, 'older than a day');
});

test("medicines: past the kit list's own printed rules, a private attention item quotes the kit list (draft)", () => {
  const took = (doses) => {
    const m = fresh();
    ordinaryDays(m, 110, 120);
    for (const [medicine, amount, hours] of doses) put(m, 120, 'medicines', medicineValue({ medicine, amount, name: 'Eye drops' }), 'crew-1', { source: 'medicine-log', time: hoursBefore(120, hours) });
    return judgeOn(m, 120);
  };
  // Ibuprofen 400 mg, 2 tablets five times within an hour: 10 tablets, more than "No more than 8 tablets every 24 hours".
  const ten = took([0.9, 0.7, 0.5, 0.3, 0.1].map((h) => ['ibuprofen', 2, h]));
  const it = tellOf(ten);
  assert.deepEqual([it.rule, it.level, it.cell.indicator, it.who, it.draft, it.private], ['kit', LEVEL.ATTENTION, 'medicines', 'crew medical officer', true, true]);
  assert.equal(it.text, 'Ibuprofen 400 mg: 10 tablets in the last 24 hours. The kit list says: "No more than 8 tablets every 24 hours. Take with food." Tell the crew medical officer, or your flight surgeon (a draft rule from the kit list of 2015; the flight surgeons set the real one).');
  assert.equal(it.short, "Ibuprofen: 10 tablets in 24 hours, more than the kit list's 8");
  assert.equal(it.entries.length, 5);
  assert.match(it.source.url, /governmentattic/);
  assert.equal(headlineFor('1 May 2026', ten), ATTENTION_ONLY);
  assert.equal(took([0.9, 0.7, 0.5, 0.3].map((h) => ['ibuprofen', 2, h])).body.level, LEVEL.FINE, '8 tablets is the limit itself');
  assert.equal(took([30, 20, 10, 5, 1].map((h) => ['ibuprofen', 2, h])).body.level, LEVEL.FINE, `only the last ${KIT_HOURS} hours count`);
  assert.match(tellOf(took([...[6, 5, 4, 3, 2, 1].map((h) => ['acetaminophen', 2, h]), ['acetaminophen', 0.5, 0.5]])).text, /^Acetaminophen \(paracetamol\) 325 mg: 12\.5 tablets in the last 24 hours\. The kit list says: "No more than 12 tablets every 24 hours\."/);
  // A sleep medicine and one whose note says "Do not use with sleep meds", in one night: both notes are quoted.
  const night = tellOf(took([['zolpidem', 1, 3], ['promethazine', 1, 2]]));
  assert.match(night.text, /^Zolpidem 10 mg \(GMT \d+\/09:00\) and Promethazine 25 mg \(GMT \d+\/10:00\), within 12 hours of each other\. The kit list says of Zolpidem: "Do not use with other sleep meds\." Of Promethazine: "May cause sedation and impair performance\. Do not use with sleep meds\." Tell the crew medical officer/);
  assert.equal(night.short, 'Zolpidem with Promethazine: the kit list says not together');
  assert.match(tellOf(took([['melatonin', 1, 5], ['zolpidem', 0.5, 4]])).text, /\. The kit list says: "Do not use with other sleep meds\." Tell/);
  assert.equal(took([['zolpidem', 1, 30], ['promethazine', 1, 20]]).body.level, LEVEL.ATTENTION, 'the later one was taken in the last 24 hours');
  for (const [doses, why] of [
    [[['promethazine', 1, 3], ['meclizine', 1, 2]], 'two anti-nausea medicines: the kit list does not forbid that'],
    [[['zolpidem', 0.5, 20], ['zolpidem', 0.5, 3]], 'the same medicine twice is not "other sleep meds"'],
    [[['zolpidem', 1, 16], ['promethazine', 1, 2]], `more than ${RULES.kitNightHours} hours apart`],
    [[['melatonin', 1, 3], ['ibuprofen', 2, 2], ['other', 10, 1], ['other', 10, 0.5]], 'no rule for these'],
  ]) assert.equal(took(doses).body.level, LEVEL.FINE, why);
  // Both rules at once: one item, both findings.
  const both = tellOf(took([...[0.9, 0.7, 0.5, 0.3, 0.1].map((h) => ['ibuprofen', 2, h]), ['zolpidem', 1, 3], ['promethazine', 1, 2]]));
  assert.deepEqual(both.findings.map((f) => f.rule), ['max', 'night']);
  assert.equal(both.short, "Ibuprofen: 10 tablets in 24 hours, more than the kit list's 8; Zolpidem with Promethazine: the kit list says not together");
});

test("the person's own logs never raise more than attention, so they never become a crew line; the example flight raises none", () => {
  const m = fresh();
  ordinaryDays(m, 110, 120);
  put(m, 120, 'symptoms', { symptom: 'backPain', severity: 10 }, 'crew-1', { source: 'symptom-log', time: hoursBefore(120, 1) });
  for (const h of [0.9, 0.7, 0.5, 0.3, 0.1]) put(m, 120, 'medicines', medicineValue({ medicine: 'ibuprofen', amount: 2 }), 'crew-1', { source: 'medicine-log', time: hoursBefore(120, h) });
  put(m, 120, 'visionCheck', 'vision and grid changed', 'crew-1', { source: 'eye-self-check', time: at(120, 9) });
  const a = judgeOn(m, 120);
  const tells = a.body.items.filter((x) => x.kind === 'tell');
  assert.deepEqual(tells.map((x) => x.cell.indicator).sort(), ['medicines', 'symptoms', 'visionCheck']);
  for (const x of tells) assert.equal(x.level, LEVEL.ATTENTION, x.rule);
  assert.equal(a.body.level, LEVEL.ATTENTION);
  assert.ok(!a.body.items.some((x) => x.cell && x.cell.private && ['red', 'camera'].includes(x.kind)), 'crew lines carry only urgent red limits and alarms');
  assert.ok(a.body.items.every((x, i, all) => i === 0 || all[i - 1].level >= x.level), 'most important first');
  const flight = flightMachine();
  for (const p of CREW) assert.ok(!assess({ machine: flight, person: p, cells: CELLS, mission: MISSION, now }).body.items.some((x) => x.kind === 'tell'), p.id);
});

test('the new rules are drafts with their sources, and the cells say the same numbers', () => {
  for (const k of ['symptomTellAt', 'kitNightHours', 'eyeAnswer']) {
    assert.equal(RULE_NOTES[k].draft, true, k);
    assert.match(RULE_NOTES[k].url, /^https:\/\/[^\s]+$/, k);
    assert.doesNotMatch(RULE_NOTES[k].text, new RegExp(`[${String.fromCharCode(0x2013, 0x2014)}]`), k);
  }
  const cell = (indicator) => CELLS.find((c) => c.indicator === indicator);
  assert.match(cell('symptoms').normText, new RegExp(`a rating of ${RULES.symptomTellAt} or more in the last ${RULES.symptomHours} hours shows as "attention"`));
  assert.match(cell('medicines').normText, /kit list's own printed rules/);
  assert.match(cell('visionCheck').normText, /until a later "No change" \(a draft rule/);
  assert.equal(KIT_HOURS, 24, 'the kit list says "every 24 hours"');
});
